#nullable enable
using System;
using System.Collections.Generic;
using System.Linq;

namespace ModConfigEnhance.Overview;
/// <summary>The log window is written in Simplified Chinese and translated here by
/// replacing known phrases. 2.3.8: Traditional Chinese added (it used to show Simplified); generated by
/// 验证/发布前审查/diag_add_tw.py.
/// 1.1.0（MCE）：照抄 IGMM（整合包切换窗口的词条已删，MCE 没有那个窗口）；导出选项的两条说明随 LogWindow 改成 MCE 的诊断内容。</summary>
