{
    private static readonly (string Simplified, string English, string Traditional)[] Phrases =
    {
        ("运行日志", "Runtime logs", "執行日誌"),
        ("日志等级", "Log level", "日誌等級"), ("模组／来源", "Mod / source", "模組／來源"),
        ("日志正文", "Log message", "日誌內文"), ("时间（* 接收时间）", "Time (* received)", "時間（* 接收時間）"),
        ("搜索日志正文、模组名……", "Search messages or mods...", "搜尋日誌內文、模組名稱……"), ("暂停刷新", "Pause", "暫停重新整理"),
        ("继续刷新", "Resume", "繼續重新整理"), ("跟随：开", "Follow: on", "跟隨：開"),
        ("跟随：关", "Follow: off", "跟隨：關"), ("跳到顶部", "Jump to top", "跳到頂部"),
        ("跳到底部", "Jump to bottom", "跳到底部"), ("重复报错 · 按首次出现排序", "Repeated errors - first occurrence order", "重複錯誤 · 依首次出現排序"),
        ("首次", "First", "首次"), ("最近", "Latest", "最近"),
        ("重复", "Repeated", "重複"), ("新增", "New", "新增"),
        ("条/秒", "entries/s", "條/秒"), ("条／秒", "entries/s", "條／秒"),
        ("条", "entries", "條"), ("连续重复", "Consecutive repeats", "連續重複"),
        ("自定义日志来源", "Custom log sources", "自訂日誌來源"), ("全部模组", "All mods", "全部模組"),
        ("模组：", "Mod: ", "模組："), ("严重错误", "Fatal", "嚴重錯誤"),
        ("未识别", "Unknown", "未識別"), ("调试", "Debug", "除錯"),
        ("信息", "Info", "資訊"), ("警告", "Warning", "警告"),
        ("错误", "Error", "錯誤"), ("全部", "All", "全部"),
        ("复制选中", "Copy selection", "複製選取"), ("复制整条", "Copy record", "複製整條"),
        ("复制筛选结果", "Copy filtered", "複製篩選結果"), ("展开／收起栈", "Toggle stack", "展開／收合堆疊"),
        ("调用栈已收起", "Stack collapsed", "呼叫堆疊已收合"), ("导出当前自定义日志", "Export current custom log", "匯出目前自訂日誌"),
        ("BepInEx 日志", "BepInEx log", "BepInEx 日誌"), ("游戏日志", "Game log", "遊戲日誌"),
        ("两种日志", "Both logs", "兩種日誌"), ("附带版本与模组信息", "Include version and mod information", "附帶版本與模組資訊"),
        ("选择位置并导出", "Choose location and export", "選擇位置並匯出"), ("导出完整来源，不受搜索筛选影响。日志正文保留原文。", "Exports the complete source, regardless of search filters. Log text is preserved.", "匯出完整來源，不受搜尋篩選影響。日誌內文保留原文。"),
        ("仅用于 Debug 和故障排查：附带游戏、BepInEx 与 ModConfig Enhance 版本，模组列表及加载／启用状态，基础组件；不含任何配置值。", "For debugging and troubleshooting only: includes game, BepInEx and ModConfig Enhance versions, the mod list with loaded/enabled states, and core components. No configuration values are included.", "僅用於除錯和故障排查：附帶遊戲、BepInEx 與 ModConfig Enhance 版本，模組清單及載入／啟用狀態，基礎組件；不含任何設定值。"), ("旧日志无时间显示 —；导出完整来源", "Historical entries without timestamps show -; export includes the full source", "舊日誌無時間顯示 —；匯出完整來源"),
        ("未接入自定义日志", "No custom log source registered", "未接入自訂日誌"), ("已暂停刷新", "Paused", "已暫停重新整理"),
        ("文字选择中，点击空白清除选择", "Selecting text; click to clear", "文字選取中，點擊空白處清除選取"), ("导出失败：", "Export failed: ", "匯出失敗："),
        ("导出完成：", "Export complete: ", "匯出完成："), ("导出完成（固定位置）：", "Export complete (fixed folder; the save dialog could not open): ", "匯出完成（固定位置）："), ("正在后台导出……", "Exporting in background...", "正在背景匯出……"),
        ("未选择自定义日志来源。", "No custom log source selected.", "未選擇自訂日誌來源。"),
        ("关闭", "Close", "關閉"), ("取消", "Cancel", "取消"),
        (" 行", " lines", " 行"),
    };
    private static readonly (string From, string En, string Tw)[] Longest = Phrases.OrderByDescending(p => p.Simplified.Length).Select(p => (p.Simplified, p.English, p.Traditional)).ToArray();
    internal static string Text(string value)
    {
        string probe = Loc.T("en", "zh-cn", "zh-tw");
        if (probe == "zh-cn") return value;
        bool english = probe == "en";
        foreach (var pair in Longest) value = value.Replace(pair.From, english ? pair.En : pair.Tw);
        return value;
    }
    internal static string Script(string source) => Text(source);
}
